// Une los fragmentos recuperados en un solo CONTEXTO para el agente.
// Distingue 4 estados del RAG para poder registrarlos y decidir después.
const UMBRAL = 0.65; // similitud mínima (coseno) para considerar un fragmento relevante
const consulta = $('Loop consultas').first().json;
const items = $input.all();

let rag_estado = 'ok';
let fragmentos = [];
if (items.some(i => i.json.error)) {
  rag_estado = 'error'; // Supabase u Ollama no respondieron (después de los reintentos)
} else {
  fragmentos = items
    .filter(i => i.json.document && i.json.document.pageContent)
    .map(i => ({
      texto: String(i.json.document.pageContent).replace(/^search_document:\s*/, '').replace(/[{}]/g, ''),
      fuente: i.json.document.metadata?.archivo || 'sin nombre',
      score: Number(i.json.score || 0),
    }));
  if (fragmentos.length === 0) rag_estado = 'sin_resultados';
}

const relevantes = fragmentos.filter(f => f.score >= UMBRAL);
const similitud_max = fragmentos.length ? Math.max(...fragmentos.map(f => f.score)) : 0;
if (rag_estado === 'ok' && relevantes.length === 0) rag_estado = 'baja_similitud';

const contexto = relevantes.length
  ? relevantes.map((f, i) => `[Fuente ${i + 1}: ${f.fuente}]\n${f.texto}`).join('\n\n')
  : 'SIN CONTEXTO RELEVANTE';

return [{ json: {
  ...consulta,
  contexto,
  rag_estado,
  similitud_max: Number(similitud_max.toFixed(3)),
  fuentes_recuperadas: [...new Set(relevantes.map(f => f.fuente))].join(', '),
} }];

