// Validación de la salida del agente ANTES de actuar (registrar, avisar, responder).
// La IA propone; estas reglas deciden.
const o = $input.first().json.output || {};
const c = $('Armar contexto').first().json;
const RESPALDO = `Hola${c.nombre ? ' ' + c.nombre.split(' ')[0] : ''}, recibimos tu consulta. Un asesor de Auto Concierge te va a contactar dentro de las 4 horas hábiles.`;

const resp = typeof o.respuesta_cliente === 'string' ? o.respuesta_cliente.trim() : '';
const tipos = ['cotizacion', 'ficha_tecnica', 'documentacion_tramites', 'reserva_pago', 'operacion_realizada', 'otro'];
const respuesta_valida = resp.length > 0 && resp.length <= 1200 && !/^(null|undefined|n\/a)$/i.test(resp) && tipos.includes(o.tipo);
// Defensa extra: si el modelo escribió un CBU o un número largo, no se envía.
const filtra_datos = /\b\d{20,22}\b/.test(resp);

const necesita_docs = ['ficha_tecnica', 'documentacion_tramites'].includes(o.tipo);
let derivar = o.derivar === true
  || (o.estado_stock === 'no_reconocido' && ['cotizacion', 'reserva_pago'].includes(o.tipo))
  || o.contexto_suficiente === false
  || (necesita_docs && c.rag_estado !== 'ok')
  || !respuesta_valida || filtra_datos;

const enviar_datos_pago = respuesta_valida && !filtra_datos && o.enviar_datos_pago === true && o.tipo === 'reserva_pago';
if (enviar_datos_pago) derivar = true;

const prioridad = !respuesta_valida ? 'REVISAR'
  : o.estado_stock === 'en_stock' ? 'ALTA'
  : o.estado_stock === 'sin_stock' ? 'BAJA'
  : derivar ? 'REVISAR' : 'INFO';

const estado = !respuesta_valida ? 'REVISAR · respuesta inválida del agente'
  : filtra_datos ? 'REVISAR · la respuesta incluía números de cuenta'
  : derivar ? 'DERIVADA' : 'RESPONDIDA';

return [{ json: {
  fecha: c.fecha, consulta_id: c.consulta_id, canal: c.canal, nombre: c.nombre, email: c.email,
  telefono: c.telefono, mensaje: c.mensaje, mensaje_id_origen: c.mensaje_id_origen,
  tipo: o.tipo ?? '', modelo_detectado: o.modelo_detectado ?? '', version_detectada: o.version_detectada ?? '',
  estado_stock: o.estado_stock ?? '', colores_disponibles: o.colores_disponibles ?? '',
  contexto_suficiente: o.contexto_suficiente === true ? 'sí' : 'no',
  fuentes_usadas: String(o.fuentes_usadas || c.fuentes_recuperadas || '').replace(/Fuente \d+:\s*/g, ''),
  rag_estado: c.rag_estado, similitud_max: c.similitud_max,
  enviar_datos_pago, prioridad, derivar, estado,
  respuesta_cliente: (respuesta_valida && !filtra_datos) ? resp : RESPALDO,
  resumen_vendedor: o.resumen_vendedor || 'Revisar la consulta a mano.',
  notificar: derivar || prioridad === 'ALTA',
  http_status: 200,
  latencia_s: Number(((Date.now() - Number(c.inicio_ms || Date.now())) / 1000).toFixed(1)),
} }];

// Agrega los datos oficiales de pago desde la hoja Config (nunca desde el LLM).
// Valida el CBU antes de enviarlo: si algo no cierra, no se envía y se deriva.
const cfg = {};
for (const i of $input.all()) if (i.json.clave) cfg[i.json.clave] = String(i.json.valor ?? '').trim();
const base = $('Validar salida').first().json;
const cbu_ok = /^\d{22}$/.test(cfg.cbu || '') && (cfg.titular || '').length > 0;

if (!cbu_ok) {
  return [{ json: { ...base, enviar_datos_pago: false, derivar: true, notificar: true, prioridad: 'REVISAR',
    estado: 'REVISAR · datos de pago no disponibles o inválidos',
    respuesta_cliente: base.respuesta_cliente.replace(/Debajo te dejamos[^.]*\.\s*/i, '') + '\n\nLos datos oficiales para la seña te los envía un asesor.' } }];
}
const bloque = [
  '', '',
  `Datos oficiales para la seña (solo a nombre de ${cfg.titular}):`,
  `- Banco: ${cfg.banco}`,
  `- CBU: ${cfg.cbu}`,
  `- Alias: ${cfg.alias}`,
  `- CUIT: ${cfg.cuit}`,
  'Después de transferir, respondé este mensaje con el comprobante. Nunca transfieras a cuentas de personas.',
].join('\n');
return [{ json: { ...base, respuesta_cliente: base.respuesta_cliente + bloque } }];

